# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">AKARSU AŞINIM VE BİRİKİM ŞEKİLLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">AKARSU AŞINIM ŞEKİLLERİ (Eğim ve Hız Fazla)</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• Vadiler: Çentik (V), Boğaz, Kanyon, Asimetrik,</text>\n  <text x="44" y="104" font-size="10.5" fill="#1e3a8a">Geniş Tabanlı (Alüvyal Tabanlı) Vadi</text>\n  <text x="34" y="126" font-size="11" fill="#1e3a8a">• Şelale (Çağlayan) ve Dev Kazanı</text>\n  <text x="34" y="148" font-size="11" fill="#1e3a8a">• Kırgıbayır (Badlands) ve Peribacaları</text>\n  <text x="34" y="170" font-size="11" fill="#1e3a8a">• Plato (Çevresine göre yüksek düz aşınım yüzeyi)</text>\n  <text x="34" y="192" font-size="11" fill="#1e3a8a">• Peneplen (Yontukdüz — Aşınımın son evresi)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">AKARSU BİRİKİM ŞEKİLLERİ (Eğim Azaldığında)</text>\n  <text x="370" y="88" font-size="11" fill="#14532d">• Birikinti Konisi ve Birikinti Yelpazesi</text>\n  <text x="370" y="110" font-size="11" fill="#14532d">• Dağ Eteği Ovası ve Dağ İçi Ovası</text>\n  <text x="370" y="132" font-size="11" fill="#14532d">• Taban Seviyesi Ovası ve Irmak Adası (Kum Adası)</text>\n  <text x="370" y="154" font-size="11" fill="#14532d">• Delta Ovası (Deniz içinde alüvyal birikim: Çukurova,</text>\n  <text x="380" y="170" font-size="10.5" fill="#14532d">Bafra, Çarşamba, Silifke, Menemen, Balat)</text>\n  <text x="370" y="194" font-size="11" font-weight="bold" fill="#15803d">• Ortak (Hem Aşınım Hem Birikim): Menderes ve Taraça (Seki)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Akarsuyun aşındırması deniz seviyesine (taban seviyesine) doğru ağızdan kaynağa (geriye) doğru ilerler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">RÜZGÂR VE BUZUL AŞINIM-BİRİKİM ŞEKİLLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">RÜZGÂR ŞEKİLLERİ (Kurak ve Yarı Kurak İklim)</text>\n  <text x="34" y="88" font-size="11" font-weight="bold" fill="#a16207">Aşınım Şekilleri (Korozyon / Deflasyon):</text>\n  <text x="34" y="108" font-size="10.8" fill="#713f12">• Mantarkaya (Şeytan Masası) ve Şahit Kaya (Tepe)</text>\n  <text x="34" y="126" font-size="10.8" fill="#713f12">• Yardang (Oluklar), Tafoni (Kovuklar) ve Hamada (Çöl Kaldırımı)</text>\n  <text x="34" y="150" font-size="11" font-weight="bold" fill="#a16207">Birikim Şekilleri:</text>\n  <text x="34" y="170" font-size="10.8" fill="#713f12">• Lös (İnce rüzgâr toprağı), Kumullar ve Barkan (Hilal kumul)</text>\n  <text x="34" y="192" font-size="10.2" fill="#475569">Türkiye\'de en çok İç Anadolu (Konya-Karapınar) ve Güneydoğu\'da.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#0284c7" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0369a1">BUZUL (GLASYAL) ŞEKİLLERİ (Soğuk İklim / Yüksek Dağ)</text>\n  <text x="370" y="88" font-size="11" font-weight="bold" fill="#0284c7">Aşınım Şekilleri:</text>\n  <text x="370" y="108" font-size="10.8" fill="#0c4a6e">• Sirk Çukuru (Buzul Yalağı), Buzul Vadisi (U Profili / Tekne)</text>\n  <text x="370" y="126" font-size="10.8" fill="#0c4a6e">• Hörgüçkaya ve Boynuz (Horn) Tepeler, Asılı Vadi</text>\n  <text x="370" y="150" font-size="11" font-weight="bold" fill="#0284c7">Birikim Şekilleri:</text>\n  <text x="370" y="170" font-size="10.8" fill="#0c4a6e">• Moren (Buzultaş), Drumlin (Balina sırtı tepe) ve Sander Düzlüğü</text>\n  <text x="370" y="192" font-size="10.2" fill="#475569">Türkiye\'de yüksek dağ zirvelerinde (Cilo, Kaçkar, Ağrı, Aladağlar).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Türkiye\'de yer şekillerini en fazla şekillendiren dış kuvvet AKARSULAR, en az şekillendiren ise BUZULLARDIR.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DALGA VE AKINTI AŞINIM-BİRİKİM ŞEKİLLERİ İLE KIYI TİPLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">DALGA AŞINIM VE BİRİKİM ŞEKİLLERİ</text>\n  <text x="34" y="88" font-size="11" font-weight="bold" fill="#c2410c">Aşınım (Derin / Dağların Paralel Olduğu Kıyılar):</text>\n  <text x="34" y="106" font-size="10.8" fill="#7c2d12">• Falez (Yalıyar), Aşınım Düzlüğü (Abrazyon Platformu),</text>\n  <text x="44" y="122" font-size="10.5" fill="#7c2d12">Doğal Köprü ve Deniz Mağaraları (Doğu Karadeniz, Antalya)</text>\n  <text x="34" y="146" font-size="11" font-weight="bold" fill="#c2410c">Birikim (Sığ / Kıta Sahanlığı Geniş Kıyılar):</text>\n  <text x="34" y="164" font-size="10.8" fill="#7c2d12">• Kumsal (Plaj), Kıyı Oku, Kıyı Kordonu</text>\n  <text x="34" y="182" font-size="10.8" fill="#7c2d12">• Lagün (Deniz Kulağı: Büyükçekmece, Küçükçekmece, Terkos)</text>\n  <text x="34" y="198" font-size="10.8" fill="#7c2d12">• Tombolo (Saplı Ada: Kapıdağ Yarımadası, Sinop)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">BAŞLICA KIYI TİPLERİ VE TÜRKİYE ÖRNEKLERİ</text>\n  <text x="370" y="88" font-size="10.8" fill="#581c87">• Boyuna Kıyı: Dağlar kıyıya paralel (Karadeniz ve Akdeniz)</text>\n  <text x="370" y="108" font-size="10.8" fill="#581c87">• Enine Kıyı: Dağlar kıyıya dik (Ege kıyıları — Edremit-Kuşadası)</text>\n  <text x="370" y="128" font-size="10.8" fill="#581c87">• Ria Kıyı: Eski akarsu vadilerinin sular altında kalması</text>\n  <text x="380" y="144" font-size="10.2" fill="#581c87">(İstanbul ve Çanakkale Boğazları, Haliç, Güneybatı Ege)</text>\n  <text x="370" y="164" font-size="10.8" fill="#581c87">• Dalmaçya Kıyı: Kıyıya paralel dağ sıraları (Finike-Kaş)</text>\n  <text x="370" y="184" font-size="10.8" fill="#581c87">• Limanlı Kıyı: Geniş vadilerin koylarla kapanması (Büyükçekmece)</text>\n  <text x="370" y="200" font-size="10.2" font-weight="bold" fill="#7e22ce">• Fiyort, Skyer, Haliç ve Mercan (Atol) Türkiye\'de doğal görülmez.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bir kıyıda falez (aşınım) fazlaysa kıta sahanlığı dardır; delta ve lagün (birikim) fazlaysa kıta sahanlığı geniştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
